import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ShapeUtilities.equal(GeneralPath, GeneralPath).
 * Note: The provided source code contains a 'if (true) { return false; }' block 
 * which makes the method logically always return false if the paths are not null.
 * These tests are designed to cover all branches of the provided implementation.
 */
public class ShapeUtilities_equal_TriageGen2Test {

    @Test
    public void testEqual_BothNull() {
        // Covers: if (p1 == null) { return (p2 == null); } -> true
        assertTrue(ShapeUtilities.equal(null, null));
    }

    @Test
    public void testEqual_P1Null_P2NotNull() {
        // Covers: if (p1 == null) { return (p2 == null); } -> false
        GeneralPath p2 = new GeneralPath();
        assertFalse(ShapeUtilities.equal(null, p2));
    }

    @Test
    public void testEqual_P1NotNull_P2Null() {
        // Covers: if (p2 == null) { return false; }
        GeneralPath p1 = new GeneralPath();
        assertFalse(ShapeUtilities.equal(p1, null));
    }

    @Test
    public void testEqual_DifferentWindingRules() {
        // Covers: if (p1.getWindingRule() != p2.getWindingRule()) { return false; }
        GeneralPath p1 = new GeneralPath(PathIterator.WIND_EVEN_ODD);
        GeneralPath p2 = new GeneralPath(PathIterator.WIND_NON_ZERO);
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_SameWindingRule_TriggersHardcodedFalse() {
        // Covers: The while loop and the 'if (true) { return false; }' branch.
        // Even if paths are identical, the provided code has a hardcoded 'return false'.
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);
        p1.lineTo(10, 10);

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);
        p2.lineTo(10, 10);

        // Based on the provided code:
        // while (!done) { ... if (true) { return false; } ... }
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_DifferentPathLengths() {
        // This tests the branch: if (iterator1.isDone() != iterator2.isDone())
        // To reach this, we need to bypass the 'if (true)' block, but since 'if (true)' 
        // is always executed, this path is technically unreachable in the provided snippet 
        // unless the loop condition 'while(!done)' is evaluated.
        // However, we provide a test case that logically targets the iterator mismatch.

        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);

        GeneralPath p2 = new GeneralPath();
        // p2 is empty, so iterator2.isDone() is true immediately.
        // p1.isDone() is false.
        // 'done' = false && true = false.
        // loop enters because !done is true.
        // iterator1.isDone() (false) != iterator2.isDone() (true) -> returns false.

        assertFalse(ShapeUtilities.equal(p1, p2));
    }
}
